parameters.new_string:
// Start a goroutine to collect results and update processedCount
var resultsWg sync.WaitGroup
resultsWg.Add(1)
go func() {
	defer resultsWg.Done()
	for range results {
		processedCount.Add(1)
	}
}()

// Wait for all workers to finish processing jobs
wg.Wait()
close(results) // Close the results channel after all workers are done sending

// Wait for the result consumer to finish draining the results channel
resultsWg.Wait()

return int(processedCount.Load()), nil
